@@ -0,0 +1,79 @@
+"use strict";
+
+/*
+ * Reproduction for no-useless-assignment false positive in try/catch.
+ * Run: node repro-19245.js   (exits 1 if the bug reproduces)
+ */
+const { Linter } = require("./lib/api");
+
+const linter = new Linter();
+const config = {
+    languageOptions: { ecmaVersion: "latest", sourceType: "module" },
+    rules: { "no-useless-assignment": "error" }
+};
+
+const cases = [
+    {
+        name: "report: return in try, value read in catch",
+        code: `
+async function fn() {
+  let intermediaryValue;
+  try {
+    intermediaryValue = 42;
+    unsafeFn();
+    return { error: undefined };
+  } catch {
+    return { intermediaryValue };
+  }
+}
+function unsafeFn() { throw new Error(); }`
+    },
+    {
+        name: "break in try, value read in catch",
+        code: `
+function fn() {
+  let v;
+  while (cond()) {
+    try {
+      v = 42;
+      unsafeFn();
+      break;
+    } catch {
+      use(v);
+    }
+  }
+}`
+    },
+    {
+        name: "control: no return in try (expected to pass)",
+        code: `
+function fn() {
+  let v;
+  try {
+    v = 42;
+    unsafeFn();
+  } catch {
+    return { v };
+  }
+}`
+    }
+];
+
+let bugReproduced = false;
+
+for (const { name, code } of cases) {
+    const messages = linter.verify(code, config);
+
+    console.log(`--- ${name}`);
+    if (messages.length === 0) {
+        console.log("    no problems (correct)");
+    } else {
+        for (const m of messages) {
+            console.log(`    ${m.line}:${m.column} ${m.ruleId}: ${m.message}`);
+        }
+        bugReproduced = true;
+    }
+}
+
+console.log(bugReproduced ? "\nBUG REPRODUCED: false positive(s) above" : "\nNo false positives");
+process.exitCode = bugReproduced ? 1 : 0;
